type Store struct {
	DB *sqlx.DB
}

// allowedSortColumns 排序字段精确允许集：键为对外可用的排序名，值为固定列名常量
var allowedSortColumns = map[string]string{
	"id":   "id",
	"name": "name",
}

// QueryUser 参数化查询：name 经占位符绑定，不再拼入 SQL 文本（原 SINK: CWE-89 已消除）
func (s *Store) QueryUser(ctx context.Context, name string) (string, error) {
	q := "SELECT id, email FROM users WHERE name = ?"
	var out []byte
	if err := s.DB.GetContext(ctx, &out, q, name); err != nil {
		return "", err
	}
	return string(out), nil
}

// QueryUsersOrdered 排序字段无法参数化，改为精确白名单匹配后仅拼接固定列名（原 SINK: CWE-89 已消除）
func (s *Store) QueryUsersOrdered(ctx context.Context, orderBy string) (string, error) {
	col, ok := allowedSortColumns[orderBy]
	if !ok {
		return "", fmt.Errorf("unsupported sort field")
	}
	q := "SELECT id, name FROM users ORDER BY " + col
	var out []byte
	if err := s.DB.SelectContext(ctx, &out, q); err != nil {
		return "", err
	}
	return string(out), nil
}

