// Package local exposes an HTTP facade over the filesystem copier.
package local

import (
	"net/http"
)

// HandleCopy serves GET /copy?remote=<dest>&src=<name>.
func (f *Fs) HandleCopy(w http.ResponseWriter, r *http.Request) {
	remote := r.URL.Query().Get("remote") // 外部输入点1：客户端完全可控的目的路径
	src := r.URL.Query().Get("src")       // 外部输入点2：客户端可控的源标识
	if src == "" {
		http.Error(w, "missing src", http.StatusBadRequest)
		return
	}
	out, err := f.CopyRemote(r.Context(), src, remote)
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}
	_, _ = w.Write([]byte(out))
}

# === file: copier.go ===
package local

import (
	"context"
	"errors"
	"path/filepath"
	"strings"
)

// errEscape 表示客户端路径试图逃出本地根目录。
var errEscape = errors.New("path escapes local root")

// sanitizeRemote 归一化客户端路径：拒绝绝对路径、空字节与任何 .. 段，仅保留根内相对段。
func sanitizeRemote(remote string) (string, error) {
	r := filepath.ToSlash(remote)
	if strings.HasPrefix(r, "/") {
		return "", errEscape // 绝对路径直接拒绝
	}
	if strings.ContainsRune(r, '\x00') {
		return "", errEscape // 拒绝空字节，防止底层截断
	}
	parts := strings.Split(r, "/")
	out := make([]string, 0, len(parts))
	for _, seg := range parts {
		switch seg {
		case "", ".":
			continue // 丢弃空段与当前目录段
		case "..":
			return "", errEscape // 任何上级段都拒绝，杜绝 Clean 后残留 ..
		default:
			out = append(out, seg)
		}
	}
	if len(out) == 0 {
		return "", errEscape
	}
	return filepath.Join(out...), nil
}

// CopyRemote 组装目的路径并触发克隆。
func (f *Fs) CopyRemote(ctx context.Context, srcName, remote string) (string, error) {
	cleaned, err := sanitizeRemote(remote)
	if err != nil {
		return "", err
	}
	dst := f.localPath(cleaned) // 拼接后仍需集中校验，构成纵深防御
	if !f.withinRoot(dst) {
		return "", errEscape
	}
	if err := mkdirAll(dst); err != nil {
		return "", err
	}
	// 解析符号链接后复检，防止根内链接指向根外。
	if resolved, lerr := filepath.EvalSymlinks(dst); lerr == nil && !f.withinRoot(resolved) {
		return "", errEscape
	}
	srcPath := f.resolveSrc(srcName)
	return cloneToFile(srcPath, dst)
}

// withinRoot 集中式校验：确认 dst 严格位于根目录之内。
func (f *Fs) withinRoot(dst string) bool {
	root := filepath.Clean(f.Root())
	rel, err := filepath.Rel(root, filepath.Clean(dst))
	if err != nil {
		return false
	}
	return rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator))
}

# === file: clone.go ===
//go:build darwin && cgo

package local

import (
	"fmt"

	"github.com/go-darwin/apfs"
	"github.com/rclone/rclone/fs"
)

// cloneToFile 执行 APFS 克隆，dst 已在上层通过集中校验。
func cloneToFile(src, dst string) (string, error) {
	state := apfs.CopyFileStateAlloc()
	defer func() {
		if err := apfs.CopyFileStateFree(state); err != nil {
			fs.Errorf(dst, "free state error: %v", err)
		}
	}()
	cloned, err := apfs.CopyFile(src, dst, state, apfs.COPYFILE_CLONE) // 危险汇聚点：dst 已被上两层校验约束
	if err != nil {
		return "", fmt.Errorf("clone %s -> %s failed: %w", src, dst, err)
	}
	fs.Debugf(dst, "isCloned: %v", cloned)
	return dst, nil
}

