# === file: iceberg/routes.go ===
package iceberg

import (
	"net/http"

	"github.com/gorilla/mux"
)

// Server implements the Iceberg REST Catalog API.
type Server struct {
	tablesManager *TablesManager
}

func NewServer(tm *TablesManager) *Server { return &Server{tablesManager: tm} }

// RegisterRoutes registers Iceberg REST Catalog routes.
func (s *Server) RegisterRoutes(router *mux.Router) {
	router.HandleFunc("/v1/namespaces/{namespace}/tables/{table}", s.Auth(s.handleLoadTable)).Methods(http.MethodGet)
	router.HandleFunc("/v1/{prefix}/namespaces/{namespace}/tables/{table}", s.Auth(s.handleLoadTable)).Methods(http.MethodGet)
}

// Auth wraps a handler; the real authentication middleware lives elsewhere.
func (s *Server) Auth(h http.HandlerFunc) http.HandlerFunc { return h }

// handleLoadTable forwards caller-controlled path variables to storage.
func (s *Server) handleLoadTable(w http.ResponseWriter, r *http.Request) {
	vars := mux.Vars(r)
	namespace, table := vars['namespace'], vars['table']
	meta, err := s.tablesManager.LoadTable(namespace, table)
	if err != nil {
		http.Error(w, err.Error(), http.StatusNotFound)
		return
	}
	w.Write(meta)
}

# === file: iceberg/sanitize.go ===
package iceberg

import (
	"fmt"
	"path/filepath"
	"regexp"
	"strings"
)

// segmentPattern is a precise whitelist for a single storage path segment:
// it must start with an alphanumeric or underscore and may contain only
// alphanumerics, underscores, dots and hyphens. A matching value can never
// be empty, ".", "..", or contain '/' or '\\' separators, so traversal
// sequences are rejected outright instead of being rewritten.
var segmentPattern = regexp.MustCompile(`^[A-Za-z0-9_][A-Za-z0-9._-]*$`)

// ValidateSegment enforces the whitelist on one caller-supplied segment
// (a namespace part or a table name).
func ValidateSegment(kind, seg string) (string, error) {
	seg = strings.TrimSpace(seg)
	if !segmentPattern.MatchString(seg) {
		return "", fmt.Errorf("invalid %s segment %q", kind, seg)
	}
	return seg, nil
}

// SanitizeNamespace normalizes a caller-supplied namespace identifier
// before it is joined into a storage path below baseDir. Every
// slash-separated segment must pass the whitelist or the whole value
// is rejected with an error.
func SanitizeNamespace(ns string) (string, error) {
	ns = strings.TrimSpace(ns)
	ns = strings.TrimPrefix(ns, '/')
	ns = strings.ReplaceAll(ns, '\\', '/')
	if ns == "" {
		return "", fmt.Errorf("namespace must not be empty")
	}
	segments := strings.Split(ns, "/")
	cleaned := make([]string, 0, len(segments))
	for _, seg := range segments {
		if seg == "" {
			continue
		}
		valid, err := ValidateSegment("namespace", seg)
		if err != nil {
			return "", err
		}
		cleaned = append(cleaned, valid)
	}
	if len(cleaned) == 0 {
		return "", fmt.Errorf("namespace must not be empty")
	}
	return strings.Join(cleaned, "/"), nil
}

// EnsureWithinBaseDir is a defense-in-depth containment check: it
// verifies that finalDir resolves at or below baseDir after Join.
func EnsureWithinBaseDir(baseDir, finalDir string) error {
	rel, err := filepath.Rel(baseDir, finalDir)
	if err != nil {
		return fmt.Errorf("path containment check failed: %v", err)
	}
	if rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return fmt.Errorf("resolved path escapes base directory")
	}
	return nil
}

# === file: iceberg/manager.go ===
package iceberg

import (
	"context"
	"path/filepath"

	"github.com/seaweedfs/seaweedfs/weed/pb/filer_pb"
)

// FilerClient provides access to the filer for storage operations.
type FilerClient interface {
	WithFilerClient(streamingMode bool, fn func(client filer_pb.SeaweedFilerClient) error) error
}

// TablesManager performs catalog storage operations through the filer.
type TablesManager struct {
	filerClient FilerClient
	baseDir     string
}

// LoadTable resolves baseDir/namespace/table via the filer.
func (m *TablesManager) LoadTable(namespace, table string) ([]byte, error) {
	ns, err := SanitizeNamespace(namespace)
	if err != nil {
		return nil, err
	}
	table, err = ValidateSegment("table", table)
	if err != nil {
		return nil, err
	}
	dir := filepath.Join(m.baseDir, ns)
	if err := EnsureWithinBaseDir(m.baseDir, dir); err != nil {
		return nil, err
	}
	var meta []byte
	err = m.filerClient.WithFilerClient(false, func(client filer_pb.SeaweedFilerClient) error {
		resp, err := client.LookupDirectoryEntry(context.Background(), &filer_pb.LookupDirectoryEntryRequest{
			Directory: dir,
			Name:      table,
		})
		if err != nil {
			return err
		}
		meta = []byte(resp.Entry.Name)
		return nil
	})
	return meta, err
}

