import os

ARTIFACT_ROOT = os.path.realpath('/srv/keras/artifacts')
ALLOWED_EXTENSIONS = {'.h5', '.keras'}


class ArtifactPathError(ValueError):
    pass


def resolve_artifact_path(name):
    # Central whitelist defense: canonicalize, then require the result to
    # stay inside ARTIFACT_ROOT and carry an allowed model extension.
    if not isinstance(name, str) or not name:
        raise ArtifactPathError('artifact name must be a non-empty string')
    if '\x00' in name:
        raise ArtifactPathError('illegal character in artifact name')
    candidate = os.path.realpath(os.path.join(ARTIFACT_ROOT, name))
    if os.path.commonpath([ARTIFACT_ROOT, candidate]) != ARTIFACT_ROOT:
        raise ArtifactPathError('path escapes the artifact root')
    if os.path.splitext(candidate)[1].lower() not in ALLOWED_EXTENSIONS:
        raise ArtifactPathError('artifact extension not allowed')
    return candidate

