// HandleUpdateRef 处理 POST /refs/update?ref=<short>&hash=<sha>
func HandleUpdateRef(w http.ResponseWriter, r *http.Request) {
	name := r.URL.Query().Get("ref")
	if name == "" {
		name = r.Header.Get("X-Ref-Name") // 备用输入通道
	}
	hash := r.URL.Query().Get("hash")
	if err := refs.UpdateRef(name, hash); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

# === file: gitapi/refs/service.go ===
package refs

import (
	"errors"
	"regexp"
	"strings"

	"example.com/gitapi/storage"
)

var ctrlSeqs = regexp.MustCompile(`[\000-\037\177]`)

var ErrInvalidReferenceName = errors.New("invalid reference name")

// ReferenceName 对应上游 plumbing.ReferenceName
type ReferenceName string

func NewBranchReferenceName(name string) ReferenceName {
	return ReferenceName("refs/heads/" + name)
}

// isRefNameByte 白名单精确允许集：仅接受 git-check-ref-format 允许的 ASCII 字符
func isRefNameByte(c byte) bool {
	switch {
	case c >= 'A' && c <= 'Z':
		return true
	case c >= 'a' && c <= 'z':
		return true
	case c >= '0' && c <= '9':
		return true
	case c == '.' || c == '_' || c == '-' || c == '/':
		return true
	default:
		return false
	}
}

// validateShortName 以拒绝代替净化：白名单字符加结构规则，杜绝父目录序列
func validateShortName(s string) error {
	if s == "" {
		return ErrInvalidReferenceName
	}
	for i := 0; i < len(s); i++ {
		if !isRefNameByte(s[i]) {
			return ErrInvalidReferenceName
		}
	}
	if strings.Contains(s, "..") {
		return ErrInvalidReferenceName
	}
	if strings.HasPrefix(s, "/") || strings.HasSuffix(s, "/") || strings.Contains(s, "//") {
		return ErrInvalidReferenceName
	}
	for _, part := range strings.Split(s, "/") {
		if strings.HasPrefix(part, ".") {
			return ErrInvalidReferenceName
		}
	}
	return nil
}

// Validate 实现 git-check-ref-format 的控制字符规则，并拒绝父目录序列与反斜杠
func (r ReferenceName) Validate() error {
	s := string(r)
	if ctrlSeqs.MatchString(s) {
		return ErrInvalidReferenceName
	}
	if strings.Contains(s, "..") || strings.ContainsRune(s, '\\') {
		return ErrInvalidReferenceName
	}
	return nil
}

// UpdateRef 校验短名后委托存储层写入（非法输入直接拒绝，不做净化替换）
func UpdateRef(short, hash string) error {
	if err := validateShortName(short); err != nil {
		return err
	}
	n := NewBranchReferenceName(short)
	if err := n.Validate(); err != nil {
		return err
	}
	return storage.WriteRef(n.String(), hash)
}

# === file: gitapi/storage/store.go ===
package storage

import (
	"errors"
	"os"
	"path/filepath"
	"strings"
)

// RefStore 将松散引用持久化到 Root（即 .git 目录）
type RefStore struct {
	Root string
}

var Default = &RefStore{Root: ".git"}

// ErrRefOutsideRoot 表示解析后的引用路径逃逸出仓库根目录
var ErrRefOutsideRoot = errors.New("reference path escapes repository root")

// WriteRef 创建父目录并写入松散引用文件，写入前强制校验路径不逃逸 Root
func WriteRef(name, hash string) error {
	rootAbs, err := filepath.Abs(Default.Root)
	if err != nil {
		return err
	}
	p := filepath.Join(rootAbs, filepath.FromSlash(name))
	rel, err := filepath.Rel(rootAbs, p)
	if err != nil {
		return err
	}
	if rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) || filepath.IsAbs(rel) {
		return ErrRefOutsideRoot
	}
	if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
		return err
	}
	return os.WriteFile(p, []byte(hash+"\n"), 0o644)
}

