package media

import (
	"fmt"
	"path/filepath"
	"strings"
)

// allowedSubtitleExts is the exact whitelist of permitted sidecar extensions.
var allowedSubtitleExts = map[string]bool{
	".srt": true,
	".vtt": true,
	".ass": true,
	".ssa": true,
	".sub": true,
}

// ResolveSidecarPath joins the client-supplied subtitle name beside the video file.
// The name must be a bare whitelisted filename and the joined result must stay
// inside the video's directory.
func ResolveSidecarPath(videoPath, name string) (string, error) {
	if name == "." || name == ".." {
		return "", fmt.Errorf("subtitle name must be a bare filename")
	}
	if strings.ContainsRune(name, '/') || strings.ContainsRune(name, '\\') {
		return "", fmt.Errorf("subtitle name must be a bare filename")
	}
	ext := strings.ToLower(filepath.Ext(name))
	if !allowedSubtitleExts[ext] {
		return "", fmt.Errorf("subtitle extension not allowed")
	}
	parentDir := filepath.Dir(videoPath)
	target := filepath.Join(parentDir, name)
	absParent, err := filepath.Abs(parentDir)
	if err != nil {
		return "", err
	}
	absTarget, err := filepath.Abs(target)
	if err != nil {
		return "", err
	}
	rel, err := filepath.Rel(absParent, absTarget)
	if err != nil {
		return "", err
	}
	if rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return "", fmt.Errorf("subtitle path escapes the media directory")
	}
	return target, nil
}

// ReadSubtitleSidecar loads external subtitle content for the HTTP response.
func ReadSubtitleSidecar(videoPath, name string) (string, error) {
	target, err := ResolveSidecarPath(videoPath, name)
	if err != nil {
		return "", err
	}
	return readSidecarFromDisk(target, filepath.Dir(videoPath))
}
