package media

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// readSidecarFromDisk normalizes then reads raw subtitle bytes from disk,
// enforcing containment inside the supplied media root before any read.
func readSidecarFromDisk(p, root string) (string, error) {
	p = filepath.Clean(p)
	absRoot, err := filepath.Abs(root)
	if err != nil {
		return "", fmt.Errorf("failed to resolve media root: %v", err)
	}
	absPath, err := filepath.Abs(p)
	if err != nil {
		return "", fmt.Errorf("failed to resolve subtitle path: %v", err)
	}
	resolvedPath, err := filepath.EvalSymlinks(absPath)
	if err != nil {
		return "", fmt.Errorf("failed to resolve subtitle path: %v", err)
	}
	rel, err := filepath.Rel(absRoot, resolvedPath)
	if err != nil {
		return "", fmt.Errorf("failed to resolve subtitle path: %v", err)
	}
	if rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return "", fmt.Errorf("subtitle path escapes the media root")
	}
	data, err := os.ReadFile(resolvedPath)
	if err != nil {
		return "", fmt.Errorf("failed to get subtitle sidecar content: %v", err)
	}
	return string(data), nil
}

