# === file: internal/tunnel/session.go ===
package tunnel

import (
	"encoding/json"
	"fmt"
	"io"
	"net"
	"net/http"
	"net/url"
	"path"
	"strings"
)

// RequestMessage is decoded straight from the public relay socket.
type RequestMessage struct {
	RequestID  string              `json:"id"`
	Method     string              `json:"method"`
	Path       string              `json:"path"`
	Query      string              `json:"query"`
	Headers    map[string][]string `json:"headers"`
	BodyBase64 string              `json:"body"`
}

// allowedMethods is an exact allowlist: only these HTTP methods may be forwarded.
var allowedMethods = map[string]bool{
	http.MethodGet:     true,
	http.MethodHead:    true,
	http.MethodPost:    true,
	http.MethodPut:     true,
	http.MethodPatch:   true,
	http.MethodDelete:  true,
	http.MethodOptions: true,
}

// SanitizePath percent-decodes the raw path with bounded iterations to defeat
// double encoding, rejects any traversal segment on the fully decoded form,
// and returns the canonical root-relative path produced by path.Clean.
func SanitizePath(raw string) (string, error) {
	if raw == "" {
		return "/", nil
	}
	decoded := raw
	for i := 0; i < 3; i++ {
		next, err := url.PathUnescape(decoded)
		if err != nil || next == decoded {
			break
		}
		decoded = next
	}
	if strings.ContainsAny(decoded, "\x00\r\n\\") {
		return "", fmt.Errorf("tunnel: illegal character in path")
	}
	for _, seg := range strings.Split(decoded, "/") {
		if seg == ".." {
			return "", fmt.Errorf("tunnel: path traversal rejected")
		}
	}
	cleaned := path.Clean("/" + decoded)
	if !strings.HasPrefix(cleaned, "/") {
		return "", fmt.Errorf("tunnel: path must stay under root")
	}
	return cleaned, nil
}

// NormalizeQuery re-parses the raw query and re-emits it in the canonical
// url.Values encoding, so separators and control characters cannot be
// smuggled into the upstream URL.
func NormalizeQuery(raw string) (string, error) {
	if raw == "" {
		return "", nil
	}
	values, err := url.ParseQuery(raw)
	if err != nil {
		return "", fmt.Errorf("tunnel: malformed query string")
	}
	return values.Encode(), nil
}

// Validate is the single centralized gate every RequestMessage must pass;
// it normalizes Path and Query in place before anything is forwarded.
func (msg *RequestMessage) Validate() error {
	if !allowedMethods[msg.Method] {
		return fmt.Errorf("tunnel: method not allowed: %q", msg.Method)
	}
	cleanPath, err := SanitizePath(msg.Path)
	if err != nil {
		return err
	}
	msg.Path = cleanPath
	cleanQuery, err := NormalizeQuery(msg.Query)
	if err != nil {
		return err
	}
	msg.Query = cleanQuery
	return nil
}

// ReadRequest reads one framed message off the wire and returns it only
// after the centralized validation gate has passed.
func ReadRequest(conn net.Conn) (RequestMessage, error) {
	var msg RequestMessage
	data, err := io.ReadAll(io.LimitReader(conn, 1<<20))
	if err != nil {
		return msg, err
	}
	if err := json.Unmarshal(data, &msg); err != nil {
		return msg, err
	}
	if err := msg.Validate(); err != nil {
		return RequestMessage{}, err
	}
	return msg, nil
}

