package tunnel

import (
	"openhole/internal/local"
)

// HandleFrame is the only dispatcher wired to the public relay.
// All field validation is centralized in ReadRequest/Validate; the old
// bypassable substring blacklist is removed entirely.
func HandleFrame(conn net.Conn, host string, port int) error {
	req, err := ReadRequest(conn)
	if err != nil {
		return err
	}
	return local.ForwardToLocal(req, host, port)
}

# === file: internal/local/forward.go ===
package local

import (
	"bytes"
	"encoding/base64"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"time"

	"openhole/internal/tunnel"
)

const maxBodyBytes = 10 * 1024 * 1024

// ForwardToLocal builds the upstream URL from typed url.URL fields so the
// path and query are re-encoded by net/url instead of raw concatenation.
func ForwardToLocal(req tunnel.RequestMessage, host string, port int) error {
	// Defense in depth: ForwardToLocal is exported and could be reached
	// without ReadRequest, so it re-runs the same centralized gate.
	if err := req.Validate(); err != nil {
		return err
	}
	target := &url.URL{
		Scheme:   "http",
		Host:     fmt.Sprintf("%s:%d", host, port),
		Path:     req.Path,
		RawQuery: req.Query,
	}
	body, _ := base64.StdEncoding.DecodeString(req.BodyBase64)
	httpReq, err := http.NewRequest(req.Method, target.String(), bytes.NewReader(body))
	if err != nil {
		return err
	}
	hc := &http.Client{Timeout: 30 * time.Second}
	resp, err := hc.Do(httpReq)
	if err != nil {
		return err
	}
	defer resp.Body.Close()
	_, _ = io.Copy(io.Discard, io.LimitReader(resp.Body, maxBodyBytes))
	return nil
}

