<?php
/**
 * Centralized CSRF defense shared by all state-changing endpoints.
 * The per-session token must be embedded in every form or AJAX request,
 * e.g. a hidden field named csrf_token filled by CsrfProtection::getToken().
 */
class CsrfProtection
{
    public static function getToken()
    {
        if (session_status() !== PHP_SESSION_ACTIVE) {
            session_start();
        }
        if (empty($_SESSION['csrf_token'])) {
            $_SESSION['csrf_token'] = bin2hex(random_bytes(32));
        }
        return $_SESSION['csrf_token'];
    }

    public static function validateRequest()
    {
        if (session_status() !== PHP_SESSION_ACTIVE) {
            session_start();
        }
        // Layer 1: strict same-origin check, exact whitelist equality only.
        if (!empty($_SERVER['HTTP_ORIGIN'])) {
            if (!hash_equals(self::expectedOrigin(), $_SERVER['HTTP_ORIGIN'])) {
                return false;
            }
        }
        // Layer 2: per-session token is mandatory and constant-time compared.
        $token = isset($_POST['csrf_token']) ? $_POST['csrf_token'] : '';
        if (!is_string($token) || $token === '') {
            return false;
        }
        return hash_equals(self::getToken(), $token);
    }

    private static function expectedOrigin()
    {
        $https = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off')
            || (isset($_SERVER['SERVER_PORT']) && (int) $_SERVER['SERVER_PORT'] === 443);
        $scheme = $https ? 'https' : 'http';
        $host = isset($_SERVER['HTTP_HOST']) ? $_SERVER['HTTP_HOST'] : '';
        return $scheme . '://' . $host;
    }
}

