package server

import (
	"errors"
	"path/filepath"
	"strings"
)

// ErrInvalidPath is returned when raw cannot be contained within root.
var ErrInvalidPath = errors.New("path escapes root")

// Resolve joins raw onto root and is the single shared guard for every
// user-supplied path. It canonicalizes the joined path and then verifies
// containment, so only paths that truly resolve inside root are allowed.
func Resolve(root, raw string) (string, error) {
	if raw == "" {
		return "", ErrInvalidPath
	}
	if filepath.IsAbs(raw) {
		return "", ErrInvalidPath
	}
	full := filepath.Join(root, filepath.Clean(raw))
	rel, err := filepath.Rel(root, full)
	if err != nil {
		return "", ErrInvalidPath
	}
	if rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return "", ErrInvalidPath
	}
	return full, nil
}
