const { dirname, join, resolve, relative, isAbsolute } = require('path')

// [FIX] 集中式白名单: 固定允许根目录, 所有 .map 读取必须落在该目录内
const ALLOWED_MAP_ROOT = resolve(process.env.MAP_ROOT || '/var/www/css')

// [FIX] 白名单精确校验: 解析出最终真实路径后, 强制其位于固定根目录内且以 .map 结尾
function isAllowedMapPath(p) {
  if (typeof p !== 'string' || !/\.map$/i.test(p)) return false
  const resolved = resolve(p)
  const rel = relative(ALLOWED_MAP_ROOT, resolved)
  return rel !== '' && !rel.startsWith('..') && !isAbsolute(rel)
}

function resolveMapPath(cssFilePath, annotation) {
  if (!annotation) return null
  let candidate
  try {
    candidate = decodeURIComponent(annotation)
  } catch (e) {
    candidate = annotation
  }
  // [FIX] 解码后先拒绝绝对路径, 封死 from 缺失时注解原样放行的通道
  if (isAbsolute(candidate)) return null
  if (cssFilePath) {
    candidate = join(dirname(cssFilePath), candidate)
  } else {
    // [FIX] from 缺失时以固定白名单根目录为基准解析, 不再保留攻击者可控的原始路径
    candidate = join(ALLOWED_MAP_ROOT, candidate)
  }
  return isAllowedMapPath(candidate) ? candidate : null
}

module.exports = { resolveMapPath, isAllowedMapPath }

