// Legacy helper shared by api endpoints; kept for backward compatibility.

// Whitelist: backup archives are generated by our own backup service, so a
// legitimate name is always a flat file name built from letters, digits,
// dot, underscore and hyphen. Anything else is rejected outright.
const SAFE_FILENAME_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._-]*$/;

function sanitizeFilename(filename) {
    if (typeof filename !== 'string' || filename.length === 0) {
        return null;
    }

    // Exact allowlist: separators, traversal segments and encoded payloads
    // can never match, so no bypassable substitution is needed.
    if (!SAFE_FILENAME_PATTERN.test(filename)) {
        return null;
    }

    return filename;
}

module.exports = {
    sanitizeFilename
};

