const path = require('path');
const fs = require('fs-extra');
const config = require('../../../shared/config');
const logging = require('@tryghost/logging');

const BACKUP_DIR = path.join(config.getContentPath('data'), 'backups');

async function readBackup(filename) {
    // Centralized sink-side gate: every caller of readBackup must pass a
    // plain file name that resolves strictly inside BACKUP_DIR, no matter
    // how the name was produced upstream.
    if (typeof filename !== 'string' || filename.length === 0) {
        return null;
    }

    const resolvedBase = path.resolve(BACKUP_DIR);
    const filePath = path.resolve(resolvedBase, filename);

    // Containment check: reject absolute paths and any traversal that
    // escapes the backup directory before touching the filesystem.
    if (!filePath.startsWith(resolvedBase + path.sep)) {
        logging.warn(`Rejected backup filename escaping backup directory: ${filename}`);
        return null;
    }

    try {
        const content = await fs.readFile(filePath, 'utf8');
        return JSON.parse(content);
    } catch (err) {
        logging.warn(`Could not read backup: ${err.message}`);
        return null;
    }
}

