package plugin

import (
	"errors"
	"io"
	"os"
	"path/filepath"
	"strings"
)

// errUnsafePath 表示外部输入未通过白名单或路径包含校验
var errUnsafePath = errors.New("refused path outside the allowed directory")

// isSafeName 白名单精确允许集：仅接受字母、数字、'-'、'_'、'.' 组成的纯文件名，
// 从根源排除路径分隔符与 '..' 等穿越片段
func isSafeName(name string) bool {
	if name == "" || len(name) > 128 {
		return false
	}
	if strings.HasPrefix(name, ".") {
		return false
	}
	for _, r := range name {
		switch {
		case r >= 'a' && r <= 'z':
		case r >= 'A' && r <= 'Z':
		case r >= '0' && r <= '9':
		case r == '-' || r == '_' || r == '.':
		default:
			return false
		}
	}
	return true
}

// containWithin 集中式路径包含校验：规范化后确认 target 未逃逸出 baseDir
func containWithin(baseDir, target string) (string, error) {
	absBase, err := filepath.Abs(filepath.Clean(baseDir))
	if err != nil {
		return "", err
	}
	absTarget, err := filepath.Abs(filepath.Clean(target))
	if err != nil {
		return "", err
	}
	rel, err := filepath.Rel(absBase, absTarget)
	if err != nil {
		return "", err
	}
	if rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return "", errUnsafePath
	}
	return filepath.Join(absBase, rel), nil
}

// Install 将下载的插件归档写入解析后的目标路径（sink）
func Install(dataHome, ref string) error {
	if !isSafeName(ref) {
		return errUnsafePath
	}
	target, err := containWithin(dataHome, ResolvePluginPath(dataHome, ref))
	if err != nil {
		return err
	}
	if err := os.MkdirAll(filepath.Dir(target), 0o755); err != nil {
		return err
	}
	dst, err := os.Create(target) // sink: 路径已通过白名单与包含双重校验
	if err != nil {
		return err
	}
	defer dst.Close()
	src, err := os.Open(archiveFor(ref))
	if err != nil {
		return err
	}
	defer src.Close()
	_, err = io.Copy(dst, src)
	return err
}

// WriteOutput 第二条流：把扫描结果写到外部指定的文件路径（sink）
func WriteOutput(target string, data []byte) error {
	if !isSafeName(target) {
		return errUnsafePath
	}
	root := outputRoot()
	safeTarget, err := containWithin(root, filepath.Join(root, target))
	if err != nil {
		return err
	}
	f, err := os.Create(safeTarget)
	if err != nil {
		return err
	}
	defer f.Close()
	_, err = f.Write(data)
	return err
}

// outputRoot 返回输出文件唯一允许写入的根目录（白名单精确允许集）
func outputRoot() string {
	home, err := os.UserHomeDir()
	if err != nil {
		return filepath.Join(os.TempDir(), "trivy-output")
	}
	return filepath.Join(home, ".trivy", "output")
}

