def _validated_ip(hostname):
    try:
        addr_infos = socket.getaddrinfo(hostname, None)
    except socket.gaierror as exc:
        raise ValueError('cannot resolve host: %s' % exc)
    ips = {info[4][0] for info in addr_infos}
    if not ips or not all(_is_public_ip(ip) for ip in ips):
        raise ValueError('host resolves to a non-public address')
    return sorted(ips)[0]


def _decode_body(body, content_type):
    charset = 'utf-8'
    if 'charset=' in content_type:
        charset = content_type.split('charset=', 1)[1].split(';', 1)[0].strip(' "\'') or 'utf-8'
    try:
        return body.decode(charset, errors='replace')
    except LookupError:
        return body.decode('utf-8', errors='replace')


def fetch_url(url):
    current_url = url
    for _hop in range(MAX_REDIRECTS + 1):
        parsed = urlsplit(current_url)
        if parsed.scheme not in ALLOWED_SCHEMES:
            raise ValueError('only http/https schemes are allowed')
        if not parsed.hostname:
            raise ValueError('URL must contain a hostname')
        if parsed.username or parsed.password:
            raise ValueError('userinfo in URL is not allowed')
        pinned_ip = _validated_ip(parsed.hostname)
        port = parsed.port or (443 if parsed.scheme == 'https' else 80)
        target = parsed.path or '/'
        if parsed.query:
            target = target + '?' + parsed.query
        conn_cls = _PinnedHTTPSConnection if parsed.scheme == 'https' else _PinnedHTTPConnection
        conn = conn_cls(parsed.hostname, pinned_ip, port=port, timeout=15)
        try:
            conn.request('GET', target, headers={'Accept': 'text/html,application/xhtml+xml'})
            resp = conn.getresponse()
            if resp.status in (301, 302, 303, 307, 308):
                location = resp.getheader('Location')
                if not location:
                    raise ValueError('redirect without Location header')
                current_url = urljoin(current_url, location)
                continue
            if resp.status >= 400:
                raise IOError('upstream returned HTTP %d' % resp.status)
            body = resp.read()
            return _decode_body(body, resp.getheader('Content-Type', ''))
        finally:
            conn.close()
    raise ValueError('too many redirects')

