<?php
namespace App\Services;

use CodeIgniter\HTTP\Files\UploadedFile;
use RuntimeException;

class UploadStorage
{
    public static function persist(UploadedFile $file, ?string $folder, ?string $name): string
    {
        $folder = $folder ?? date('Ymd');
        $name   = $name ?? $file->getClientName();

        // [FIX] 白名单精确允许集：folder 必须是单一安全目录段（仅字母/数字/下划线/连字符）
        if (! preg_match('/\A[A-Za-z0-9_-]{1,64}\z/', $folder)) {
            throw new RuntimeException('Invalid upload folder');
        }

        // [FIX] 白名单精确允许集：name 必须是纯文件名，禁止分隔符、点段与空字节
        if (! preg_match('/\A[A-Za-z0-9][A-Za-z0-9._-]{0,254}\z/', $name)
            || str_contains($name, '..')) {
            throw new RuntimeException('Invalid file name');
        }

        $target = WRITEPATH . 'uploads/' . trim($folder, '/') . '/';

        if (! is_dir($target) && ! mkdir($target, 0755, true)) {
            throw new RuntimeException('Unable to create upload folder');
        }

        $file->move($target, $name);
        return $target . $name;
    }
}
